using System;
using System.Collections.Generic;
namespace SodaDesktopTests {
 public static class CodecPacketChecks {
  static void Check(bool value,string message){if(!value)throw new InvalidOperationException(message);}
  sealed class Writer{readonly List<int> bits=new List<int>();public void Put(uint value,int count){for(int i=count-1;i>=0;i--)bits.Add((int)((value>>i)&1));}public byte[] Bytes(){var bytes=new byte[(bits.Count+7)/8];for(int i=0;i<bits.Count;i++)bytes[i/8]|=(byte)(bits[i]<<(7-i%8));return bytes;}}
  static byte[] Obu(int kind,byte[] payload){if(payload.Length>=128)throw new Exception("Test OBU size");var result=new List<byte>{(byte)(kind*8+2),(byte)payload.Length};result.AddRange(payload);return result.ToArray();}
  static byte[] Sequence(){var b=new Writer();b.Put(0,3);b.Put(0,1);b.Put(0,1);b.Put(0,1);b.Put(0,1);b.Put(0,5);b.Put(0,12);b.Put(8,5);b.Put(0,1);b.Put(9,4);b.Put(8,4);b.Put(639,10);b.Put(359,9);b.Put(0,1);b.Put(0,3);b.Put(0,4);b.Put(0,1);b.Put(1,1);b.Put(1,1);b.Put(0,3);b.Put(0,1);b.Put(0,1);b.Put(0,1);b.Put(0,1);b.Put(0,2);b.Put(0,1);b.Put(0,1);b.Put(1,1);return Obu(1,b.Bytes());}
  public static void Run(){
   // Main-profile SPS, full parameter sets and an IDR; generated bytes only.
   var hevc=new SodaDesktopVideoBitstream("hevc");var sps=new byte[]{0x42,1,1,1,0x60,0,0,0,0xb0,0,0,0,0,0,120};
   var data=new List<byte>();foreach(var nal in new[]{new byte[]{0x40,1,0x80},sps,new byte[]{0x44,1,0x80},new byte[]{0x26,1,0x80}}){data.AddRange(new byte[]{0,0,0,1});data.AddRange(nal);}
   var first=hevc.Normalize(data.ToArray());Check(first.Key&&first.Codec=="hev1.1.6.L120.B0","HEVC SPS profile/tier/level");
   var length=new byte[]{0,0,0,3,0x26,1,0x80};var again=hevc.Normalize(length);Check(again.Key&&again.Data.Length>length.Length,"HEVC reset headers not repeated");
   bool rejected=false;try{new SodaDesktopVideoBitstream("hevc").Normalize(length);}catch(FormatException){rejected=true;}Check(rejected,"Headerless HEVC IDR accepted");
   rejected=false;try{hevc.Normalize(new byte[]{0,0,0,99,0x26});}catch(FormatException){rejected=true;}Check(rejected,"Truncated HEVC NAL accepted");
   var headers=new List<byte>();foreach(var nal in new[]{new byte[]{0x40,1,0x80},sps,new byte[]{0x44,1,0x80}}){headers.AddRange(new byte[]{0,0,0,1});headers.AddRange(nal);}
   Check(new SodaDesktopVideoBitstream("hevc").Normalize(length,headers.ToArray()).Key,"Media-type-only HEVC headers not included");
   var av1=new SodaDesktopVideoBitstream("av1");var sequence=Sequence();var keyBytes=new List<byte>(sequence);keyBytes.AddRange(Obu(6,new byte[]{0x10}));var unit=av1.Normalize(keyBytes.ToArray());Check(unit.Key&&unit.Codec=="av01.0.08M.08","AV1 actual sequence profile/level/depth");
   var repeated=av1.Normalize(Obu(6,new byte[]{0x10}));Check(repeated.Key&&repeated.Data.Length>3,"AV1 reset sequence header missing");
   foreach(byte value in new byte[]{0x50,0x70,0x80})Check(!av1.Normalize(Obu(6,new[]{value})).Key,"AV1 intra-only/switch/show-existing marked random access");
   rejected=false;try{av1.Normalize(new byte[]{0x32,0xff,0xff,0xff,0xff});}catch(FormatException){rejected=true;}Check(rejected,"Truncated AV1 size accepted");
   var doubleFrame=new List<byte>(Obu(6,new byte[]{0x10}));doubleFrame.AddRange(Obu(6,new byte[]{0x10}));rejected=false;try{av1.Normalize(doubleFrame.ToArray());}catch(FormatException){rejected=true;}Check(rejected,"Multiple AV1 frames accepted");
   var bgr=new byte[]{0,0,255,0,255,0,255,0,0,255,255,255};var ayuv=new byte[16];SodaDesktopH264.ConvertAyuv(bgr,ayuv,2,2);Check(ayuv[0]==240&&ayuv[1]==102&&ayuv[2]==63&&ayuv[3]==255,"Full-chroma AYUV ordering");Check(ayuv[0]!=ayuv[4]&&ayuv[1]!=ayuv[5],"AYUV chroma was averaged");
   Console.WriteLine("desktop_codec_packet_checks_passed: HEVC/AV1 actual headers and random access, Annex-B/OBU bounds, repeated reset headers, AYUV full chroma");
  }
 }
}
